import{_ as t,o as r,c as l,ag as n}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Korean-Philosophy/01-Dangun-Myth.md","filePath":"philosophy/Korean-Philosophy/01-Dangun-Myth.md"}'),s={name:"philosophy/Korean-Philosophy/01-Dangun-Myth.md"};function a(i,o,e,g,h,p){return r(),l("div",null,[...o[0]||(o[0]=[n('<h2 id="단군이야기는-허구인가" tabindex="-1">단군이야기는 허구인가? <a class="header-anchor" href="#단군이야기는-허구인가" aria-label="Permalink to &quot;단군이야기는 허구인가?&quot;">​</a></h2><p>역사적 사서에는 단군이 실제로 있었던 것으로 적혀 있으며, 조선시대 학자들도 단군을 역사적 사실로 받아들였음.</p><ul><li>기원전 2333년: 단군왕검이 고조선을 건국 (『삼국유사』)</li><li>은말주초: 기자동래설 (『삼국사기』) 등</li></ul><p><strong>&#39;단군신화&#39;라는 용어는 언제부터 쓰였는가?</strong>: 우리 역사서에는 &#39;단군신화&#39;라는 용어가 등장하지 않음 — 조선사편수회 회원이었던 이마니시 류에 의해 처음 사용됨. 그러나 조선시대 학자들은 역사를 서술할 때 단군시대를 역사시대로 인식하고 있었음. 이후 이마니시 류의 측근들이 대학교수로 활동하며 이 용어가 확산됨.</p><p>이렇게 &#39;신화&#39;로 격하시킨 이유는, 조선인들의 역사로부터 나오는 공동체 의식이 너무 강해 통치하기가 어려웠기 때문 — 창씨개명과 함께 역사·문화를 왜곡하여 식민지화를 용이하게 하려는 목적.</p><h2 id="『삼국유사』의-단군이야기-해석-방식" tabindex="-1">『삼국유사』의 단군이야기 해석 방식 <a class="header-anchor" href="#『삼국유사』의-단군이야기-해석-방식" aria-label="Permalink to &quot;『삼국유사』의 단군이야기 해석 방식&quot;">​</a></h2><p>단군이야기가 실제 역사였다 해도, 그것을 표현하는 방식은 신화적임 — 이해하는 방식도 신화적으로 읽어야 함. 신화란 신에 대한 이야기가 아니라, 고대 생활세계에 대한 이야기로서 인간·자연·사회 등에 대한 조상들의 이해방식을 나타냄. 논리 이면의 비유와 상징성에 주목해야 함.</p><h2 id="『삼국유사』-단군이야기의-구조" tabindex="-1">『삼국유사』 단군이야기의 구조 <a class="header-anchor" href="#『삼국유사』-단군이야기의-구조" aria-label="Permalink to &quot;『삼국유사』 단군이야기의 구조&quot;">​</a></h2><p><strong>단군이란?</strong>: 음역하면 만주어로 하늘을 뜻하는 &#39;탕그리&#39;에서 시작되어 샤먼·제사장을 지칭. 의역하면 &#39;박달군주&#39;로, 박달은 밝은 땅·태양이 비추는 곳, 즉 조선으로 해석됨.</p><p><strong>『삼국유사』 내용 기반 분석</strong></p><ol><li><strong>고기(古記)</strong>: 『삼국유사』 이전의 역사서를 지칭 — 저자가 단군에 관한 일을 스스로 지어낸 것이 아님을 보여줌 <ul><li><strong>환인</strong>: 밝은 사람, 하느님 — 태양숭배 사상</li><li><strong>탐구인세</strong>: 인간 세상을 구하는 것을 탐구함 — 단군신화의 초점이 단순한 자연 발생 과정 설명이 아니라 <strong>인간의 삶</strong>에 있음을 보여줌</li></ul></li><li><strong>천부인</strong>: 무속적인 무구(거울, 칼, 방울) — 단군신화의 샤머니즘적 요소 <ul><li><strong>신단수</strong>: 하늘과 가장 가까운 공간</li><li><strong>신시</strong>: 돌무더기, 종교적 공간</li><li><strong>풍백·운사·우사</strong>: 바람·구름·비를 관장하는 신 — 농경생활에서 중요한 요소를 상징하며, 농경 백성을 이롭게 하려는 의지가 드러남</li></ul></li><li><strong>곰과 호랑이</strong>: 각 지방에 살던 부족의 토템으로 풀이됨 — 곰족은 농경을, 호랑이족은 수렵을 했음 <ul><li><strong>쑥과 마늘</strong>: 당시 사회가 농경사회임을 암시. 다른 존재와 함께 살아가기 위해 욕망의 통제가 필요하다는, 노력의 과정을 그린 것으로 보임</li></ul></li><li><strong>웅녀</strong>: 천신족과 웅신족의 족외혼을 상징 — 천신족은 샤머니즘을 바탕으로 한 유입족(청동문화), 웅신족은 토테미즘을 바탕으로 농경생활을 하는 토착족(신석기문화)을 의미</li></ol><h2 id="단군이야기의-의의" tabindex="-1">단군이야기의 의의 <a class="header-anchor" href="#단군이야기의-의의" aria-label="Permalink to &quot;단군이야기의 의의&quot;">​</a></h2><p>인간을 하늘과 땅의 결합물로 봄 — 신과 자연, 시간, 공간, 하늘과 땅의 결합.</p><ol><li><strong>창조신화가 아님</strong> — &#39;있음&#39;으로부터 시작 <ul><li>서양은 신이 인간을 창조함으로써 지배·피지배 관계가 형성되고, 신-인간 관계가 자연스럽게 인간-자연 관계에 대입되어 자연을 지배해야 할 대상으로 봄. 이후 신의 자리를 인간의 이성이 대체하며 인식론 등 메타적 철학이 발달했고, 다른 인간 또한 지배의 대상으로 보게 됨.</li><li>동양철학은 인간을 창조된 것이 아닌 <strong>노력의 산물</strong>로 봄 — 인식론·과학기술이 서양에 비해 덜 발달한 대신 자연친화적 세계관을 가지게 됨.</li></ul></li><li><strong>유기체적 세계관</strong>을 담고 있음 — 하늘은 신이지만 절대적인 힘을 행사하는 대상이 아니라 지상세계를 도와주는 역할로 등장. 땅은 자연과 동물성을 상징. 하늘과 땅의 조화로 인간이 탄생할 뿐 아니라, 하늘·땅·인간의 조화를 통해 농산물이 산출됨 — 부분을 구별해 그 부분만 치료하는 양의학과 달리, 유기체 전체의 조화를 우선시하는 한의학의 사고방식과도 통함.</li><li><strong>인본주의 사상</strong>을 담고 있음 — 하늘이 단순히 인간 위에 군림하는 것이 아니라, 재세이화·홍익인간처럼 인간을 이롭게 할 뿐이고, 땅(생성의 의미)은 하늘과 결합해 인간세계를 풍요롭게 함.</li><li><strong>능동적이고 주체적인 인간관</strong>을 담고 있음 — 지신인 웅녀와 천신인 환웅의 결합으로 인간이 만들어짐. 동물성을 지닌 웅녀가 육체적 수행을 통해 이를 극복하고 인간이 되었다는 점에서, 신성은 하늘에도 있지만 스스로 인간이 된 존재에도 내재함을 보여줌 — 인간은 신성과 동물성을 모두 지니는 <strong>신형묘합적 존재</strong>.</li></ol>',14)])])}const _=t(s,[["render",a]]);export{d as __pageData,_ as default};
